import{_ as o,o as a,c,ai as p}from"./chunks/framework.Ba-VnP44.js";const E=JSON.parse('{"title":"业务流程管理 BPM · OpenBiz 第八个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/bpm.md","filePath":"apps/openbiz/bpm.md"}'),d={name:"apps/openbiz/bpm.md"};function i(n,e,r,t,l,s){return a(),c("div",null,[...e[0]||(e[0]=[p('<h1 id="业务流程管理-bpm-·-openbiz-第八个独立消费者" tabindex="-1">业务流程管理 BPM · OpenBiz 第八个独立消费者 <a class="header-anchor" href="#业务流程管理-bpm-·-openbiz-第八个独立消费者" aria-label="Permalink to “业务流程管理 BPM · OpenBiz 第八个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-bpm-app</code>（<code>E:/8.cangku/for-job/openbiz-bpm-app</code>）：独立后端（端口 18088）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_bpm</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓无 BPM 域，按 OpenBiz 命名约定自建 <code>openbiz_bpm_*</code> 表，在其多租户基座之上实现「流程定义 + 流程实例双状态机 + 统计」最小闭环。验证 OpenBiz V0.2「更多独立 consumer」目标。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_bpm_process</code> / <code>openbiz_bpm_instance</code> 表 + Mapper / Service / Controller <ul><li>流程定义状态机：<code>DESIGN → DEPLOYED → RUNNING ⇄ SUSPENDED</code>，<code>DEPLOYED/RUNNING/SUSPENDED → RETIRED</code>（不可逆终态）</li><li>流程实例状态机：<code>STARTED → RUNNING ⇄ SUSPENDED</code>，<code>RUNNING → COMPLETED / TERMINATED</code>（终态）</li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>创建流程(<code>DESIGN</code>) → 部署(<code>DEPLOYED</code>) → 启动(<code>RUNNING</code>) → 挂起(<code>SUSPENDED</code>) → 恢复(<code>RUNNING</code>)；运行中再部署被 <code>ILLEGAL_TRANSITION</code> 拒绝。建实例(<code>STARTED</code>) → 启动(<code>RUNNING</code>) → 挂起 → 恢复 → 完成(<code>COMPLETED</code>)；完成后挂起被拒。统计接口 <code>GET /api/bpm/stats</code> 返回流程 / 实例各状态数量。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-bpm-app</code>（含 README 与 E2E 脚本，端口 18088）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>本例是 OpenBiz 承载「流程类系统」的试水。后续可叠加可视化设计器、审批规则、任务指派与轨迹审计，作为 OA / 审批中心的核心底座。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const N=o(d,[["render",i]]);export{E as __pageData,N as default};
